import { helpers } from "simplicit";

import Article from "models/Article";
import renderForm from "views/admin/articles/Form";

// A form edits a detached copy: the collection record is what the page
// displays and what reactions/articles refreshes from the server, and
// `changes()` is the diff between the two.
class Articles {
  edit() {
    renderForm(Article.byId(helpers.params.id).clone());
  }
}

export default Articles;
